import React, { useState, useCallback, useEffect } from 'react';
import {
  View,
  Text,
  StyleSheet,
  ScrollView,
  ActivityIndicator,
  RefreshControl,
  TouchableOpacity,
  Alert,
  Modal,
} from 'react-native';
import { useRouter } from 'expo-router';
import { useSafeAreaInsets } from 'react-native-safe-area-context';
import {
  Edit2,
  LogOut,
  MapPin,
  Phone,
  Linkedin,
  Briefcase,
  GraduationCap,
  ChevronRight,
  X,
} from 'lucide-react-native';
import { useAuth } from '@/contexts/AuthContext';
import { authenticatedGet } from '@/utils/api';
import { COLORS } from '@/constants/theme';
import { AnimatedPressable } from '@/components/AnimatedPressable';

interface Experience {
  title: string;
  company: string;
  start_date?: string;
  end_date?: string;
  description?: string;
}

interface Education {
  degree: string;
  institution: string;
  year?: string;
}

interface Profile {
  id: string;
  headline?: string;
  summary?: string;
  location?: string;
  phone?: string;
  linkedin_url?: string;
  skills?: string[];
  experience?: Experience[];
  education?: Education[];
  cv_score?: number;
  cv_filename?: string;
  updated_at?: string;
}

export default function ProfileScreen() {
  const router = useRouter();
  const insets = useSafeAreaInsets();
  const { user, signOut } = useAuth();

  const [profile, setProfile] = useState<Profile | null>(null);
  const [loading, setLoading] = useState(true);
  const [refreshing, setRefreshing] = useState(false);
  const [error, setError] = useState('');
  const [showSignOutModal, setShowSignOutModal] = useState(false);

  const fetchProfile = useCallback(async () => {
    console.log('[Profile] Fetching profile');
    try {
      const data = await authenticatedGet<Profile>('/api/profile');
      setProfile(data);
      setError('');
    } catch (e: any) {
      console.error('[Profile] Fetch error:', e);
      if (!e?.message?.includes('404')) {
        setError('Failed to load profile.');
      }
    } finally {
      setLoading(false);
      setRefreshing(false);
    }
  }, []);

  useEffect(() => {
    fetchProfile();
  }, [fetchProfile]);

  const onRefresh = useCallback(() => {
    setRefreshing(true);
    fetchProfile();
  }, [fetchProfile]);

  const handleSignOut = async () => {
    console.log('[Profile] Sign out confirmed');
    setShowSignOutModal(false);
    try {
      await signOut();
      router.replace('/auth-screen');
    } catch (e: any) {
      console.error('[Profile] Sign out error:', e);
    }
  };

  const initials = (user?.name || user?.email || 'U')
    .split(' ')
    .map((w) => w[0])
    .slice(0, 2)
    .join('')
    .toUpperCase();

  if (loading) {
    return (
      <View style={[styles.centered, { paddingTop: insets.top }]}>
        <ActivityIndicator size="large" color={COLORS.accent} />
      </View>
    );
  }

  return (
    <>
      <ScrollView
        style={styles.container}
        contentContainerStyle={[styles.content, { paddingTop: insets.top + 16, paddingBottom: 120 }]}
        showsVerticalScrollIndicator={false}
        refreshControl={
          <RefreshControl
            refreshing={refreshing}
            onRefresh={onRefresh}
            tintColor={COLORS.accent}
            colors={[COLORS.accent]}
          />
        }
      >
        {/* Header */}
        <View style={styles.headerRow}>
          <Text style={styles.headerTitle}>Profile</Text>
          <AnimatedPressable
            style={styles.editBtn}
            onPress={() => {
              console.log('[Profile] Navigate to edit profile');
              router.push('/profile/edit');
            }}
          >
            <Edit2 size={16} color={COLORS.accent} />
            <Text style={styles.editBtnText}>Edit</Text>
          </AnimatedPressable>
        </View>

        {error ? (
          <View style={styles.errorBanner}>
            <Text style={styles.errorText}>{error}</Text>
          </View>
        ) : null}

        {/* Avatar + Name */}
        <View style={styles.avatarSection}>
          <View style={styles.avatarCircle}>
            <Text style={styles.avatarText}>{initials}</Text>
          </View>
          <Text style={styles.userName}>{user?.name || 'Your Name'}</Text>
          <Text style={styles.userEmail}>{user?.email}</Text>
          {profile?.headline ? (
            <Text style={styles.headline}>{profile.headline}</Text>
          ) : null}
        </View>

        {/* Meta Info */}
        {(profile?.location || profile?.phone || profile?.linkedin_url) && (
          <View style={styles.card}>
            {profile.location ? (
              <View style={styles.metaRow}>
                <MapPin size={16} color={COLORS.textSecondary} />
                <Text style={styles.metaText}>{profile.location}</Text>
              </View>
            ) : null}
            {profile.phone ? (
              <View style={styles.metaRow}>
                <Phone size={16} color={COLORS.textSecondary} />
                <Text style={styles.metaText}>{profile.phone}</Text>
              </View>
            ) : null}
            {profile.linkedin_url ? (
              <View style={styles.metaRow}>
                <Linkedin size={16} color={COLORS.textSecondary} />
                <Text style={styles.metaText} numberOfLines={1}>{profile.linkedin_url}</Text>
              </View>
            ) : null}
          </View>
        )}

        {/* Summary */}
        {profile?.summary ? (
          <View style={styles.card}>
            <Text style={styles.cardTitle}>About</Text>
            <Text style={styles.summaryText}>{profile.summary}</Text>
          </View>
        ) : null}

        {/* Skills */}
        {profile?.skills && profile.skills.length > 0 ? (
          <View style={styles.card}>
            <Text style={styles.cardTitle}>Skills</Text>
            <View style={styles.skillsRow}>
              {profile.skills.map((skill, i) => (
                <View key={i} style={styles.skillChip}>
                  <Text style={styles.skillChipText}>{skill}</Text>
                </View>
              ))}
            </View>
          </View>
        ) : null}

        {/* Experience */}
        {profile?.experience && profile.experience.length > 0 ? (
          <View style={styles.card}>
            <View style={styles.cardTitleRow}>
              <Briefcase size={16} color={COLORS.accent} />
              <Text style={styles.cardTitle}>Experience</Text>
            </View>
            {profile.experience.map((exp, i) => (
              <View key={i} style={[styles.timelineItem, i < profile.experience!.length - 1 && styles.timelineItemBorder]}>
                <Text style={styles.expTitle}>{exp.title}</Text>
                <Text style={styles.expCompany}>{exp.company}</Text>
                {(exp.start_date || exp.end_date) ? (
                  <Text style={styles.expDates}>
                    {exp.start_date || ''}{exp.start_date && exp.end_date ? ' – ' : ''}{exp.end_date || 'Present'}
                  </Text>
                ) : null}
                {exp.description ? (
                  <Text style={styles.expDesc} numberOfLines={3}>{exp.description}</Text>
                ) : null}
              </View>
            ))}
          </View>
        ) : null}

        {/* Education */}
        {profile?.education && profile.education.length > 0 ? (
          <View style={styles.card}>
            <View style={styles.cardTitleRow}>
              <GraduationCap size={16} color={COLORS.accent} />
              <Text style={styles.cardTitle}>Education</Text>
            </View>
            {profile.education.map((edu, i) => (
              <View key={i} style={[styles.timelineItem, i < profile.education!.length - 1 && styles.timelineItemBorder]}>
                <Text style={styles.expTitle}>{edu.degree}</Text>
                <Text style={styles.expCompany}>{edu.institution}</Text>
                {edu.year ? <Text style={styles.expDates}>{edu.year}</Text> : null}
              </View>
            ))}
          </View>
        ) : null}

        {/* Sign Out */}
        <AnimatedPressable
          style={styles.signOutBtn}
          onPress={() => {
            console.log('[Profile] Sign out button pressed');
            setShowSignOutModal(true);
          }}
        >
          <LogOut size={18} color={COLORS.error} />
          <Text style={styles.signOutText}>Sign Out</Text>
        </AnimatedPressable>
      </ScrollView>

      {/* Sign Out Confirmation Modal */}
      <Modal
        visible={showSignOutModal}
        transparent
        animationType="fade"
        onRequestClose={() => setShowSignOutModal(false)}
      >
        <View style={styles.modalOverlay}>
          <View style={styles.modalCard}>
            <Text style={styles.modalTitle}>Sign Out</Text>
            <Text style={styles.modalMessage}>Are you sure you want to sign out?</Text>
            <View style={styles.modalButtons}>
              <TouchableOpacity
                style={styles.modalCancelBtn}
                onPress={() => setShowSignOutModal(false)}
              >
                <Text style={styles.modalCancelText}>Cancel</Text>
              </TouchableOpacity>
              <TouchableOpacity
                style={styles.modalConfirmBtn}
                onPress={handleSignOut}
              >
                <Text style={styles.modalConfirmText}>Sign Out</Text>
              </TouchableOpacity>
            </View>
          </View>
        </View>
      </Modal>
    </>
  );
}

